package org.localknowledge.library;

import android.app.ActivityManager;
import android.database.sqlite.SQLiteDatabase;
import android.graphics.*;
import android.graphics.pdf.PdfRenderer;
import android.net.Uri;
import android.os.*;
import android.webkit.WebResourceResponse;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.Pattern;

/** Android equivalents of Khoj's organization, recovery and release controls. */
final class KhojFeatures {
    final NativeBackend b;final LibraryStore s;final JSONArray rules;String groupKey="";JSONArray groupCache;final Map<String,String> autoKeys=new HashMap<>();final Map<String,JSONArray> autoTopics=new HashMap<>();
    KhojFeatures(NativeBackend backend){b=backend;s=b.store;try(InputStream in=b.context.getAssets().open("khoj-topics.json")){rules=new JSONArray(new String(ModelAssets.read(in),StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException("Bundled topic rules unavailable",e);}}
    String setting(String key){JSONArray rows=s.query("SELECT value FROM settings WHERE key=?",key);return rows.length()==0?null:rows.optJSONObject(0).optString("value");}
    void save(String key,Object value){s.exec("INSERT OR REPLACE INTO settings VALUES(?,?)",key,value.toString());}
    JSONObject catalogue(){String saved=setting("khoj.topics");JSONObject topics=saved==null?new JSONObject():Json.parse(saved);try{for(JSONObject rule:LibraryStore.objects(rules)){String id="subject-"+Integer.toHexString(rule.optString("name").hashCode());if(!topics.has(id))topics.put(id,Json.obj("id",id,"name",rule.optString("name"),"basis","Suggested subject"));}if(!topics.has("misc"))topics.put("misc",Json.obj("id","misc","name","Miscellaneous","basis","Suggested subject"));}catch(JSONException e){throw new IllegalArgumentException(e);}return topics;}
    JSONArray topics(){JSONArray result=new JSONArray();JSONObject all=catalogue();Iterator<String> ids=all.keys();while(ids.hasNext())result.put(all.optJSONObject(ids.next()));return result;}
    synchronized JSONArray assigned(String id){String manual=setting("khoj.doc.topics:"+id);if(manual!=null)return array(manual);JSONObject doc=s.document(id);String semantic=setting("khoj.semantic.doc:"+id);if(semantic!=null){JSONObject suggestion=Json.parse(semantic);if(suggestion.optString("sha256").equals(doc.optString("sha256")))return suggestion.optJSONArray("topics");}String signature=doc.optString("sha256")+doc.optString("filename")+doc.optString("title");if(signature.equals(autoKeys.get(id)))return autoTopics.get(id);String text=doc.optString("filename")+" "+doc.optString("title");for(JSONObject page:LibraryStore.objects(s.query("SELECT substr(text,1,8000) text FROM pages WHERE document_id=? ORDER BY page_number LIMIT 12",id)))text+=" "+page.optString("text");JSONArray result=new JSONArray();String lower=text.toLowerCase(Locale.ROOT);for(JSONObject rule:LibraryStore.objects(rules)){boolean match=Pattern.compile(rule.optString("pattern"),Pattern.CASE_INSENSITIVE).matcher(lower).find();for(String phrase:NativeBackend.strings(rule.optJSONArray("phrases")))if(lower.contains(phrase.toLowerCase(Locale.ROOT)))match=true;if(match)result.put("subject-"+Integer.toHexString(rule.optString("name").hashCode()));}if(result.length()==0)result.put("misc");autoKeys.put(id,signature);autoTopics.put(id,result);return result;}
    static JSONArray array(String text){try{return new JSONArray(text);}catch(JSONException e){throw new IllegalArgumentException(e);}}
    synchronized JSONArray groups(){String key=s.query("SELECT id,sha256,updated_at,trashed FROM documents ORDER BY id").toString()+s.query("SELECT key,value FROM settings WHERE key LIKE 'khoj.%' AND key NOT LIKE 'khoj.move:%' AND key NOT LIKE 'khoj.reading:%' AND key NOT LIKE 'khoj.name:%' AND key NOT LIKE 'khoj.modified:%' AND key != 'khoj.library.preferences' ORDER BY key").toString();if(groupCache!=null&&key.equals(groupKey))return groupCache;Map<String,JSONArray> members=new LinkedHashMap<>();JSONObject all=catalogue();for(JSONObject topic:LibraryStore.objects(topics()))members.put(topic.optString("id"),new JSONArray());for(JSONObject doc:LibraryStore.objects(s.documents()))for(String id:NativeBackend.strings(assigned(doc.optString("id"))))if(members.containsKey(id))members.get(id).put(doc.optString("id"));JSONArray result=new JSONArray();for(String id:members.keySet()){JSONObject topic=all.optJSONObject(id);JSONArray docs=members.get(id);if(docs.length()>0||topic.optString("basis").equals("Personal topic"))result.put(Json.obj("id",id,"name",topic.optString("name"),"basis",topic.optString("basis"),"document_ids",docs,"document_count",docs.length()));}groupKey=key;groupCache=result;return result;}
    JSONArray decorate(JSONArray documents){Map<String,String> names=new HashMap<>();String prefix="khoj.name:";
        for(JSONObject row:LibraryStore.objects(s.query("SELECT key,value FROM settings WHERE key LIKE 'khoj.name:%'")))names.put(row.optString("key").substring(prefix.length()),row.optString("value"));
        for(JSONObject doc:LibraryStore.objects(documents)){String name=names.get(doc.optString("id"));if(name!=null)try{doc.put("display_title",name);}catch(JSONException ignored){}}return documents;
    }
    JSONObject info(String id){JSONObject doc=s.document(id);return Json.obj("topic_ids",assigned(id),"manual_topics",setting("khoj.doc.topics:"+id)!=null,"display_title",setting("khoj.name:"+id)==null?doc.optString("title"):setting("khoj.name:"+id),"filename",doc.optString("filename"));}
    List<String> ids(JSONObject body){Set<String> values=NativeBackend.strings(body.optJSONArray("document_ids"));if(values.isEmpty()||values.size()>2000)throw new IllegalArgumentException("Select between 1 and 2,000 files");for(String id:values)if(s.document(id).optInt("trashed")!=0)throw new IllegalArgumentException("Restore removed files first");return new ArrayList<>(values);}
    JSONObject route(String route,String method,JSONObject body)throws Exception {
        String[] p=route.split("/");
        if(route.equals("/about"))return about();
        if(route.equals("/diagnostics")&&method.equals("POST"))return diagnostics();
        if(route.equals("/organization/topics/suggest")&&method.equals("POST"))return b.smartTopics.start();
        if(route.equals("/organization"))return Json.obj("topics",topics());
        if(route.equals("/organization/topics")&&method.equals("POST")){JSONObject all=catalogue();String name=uniqueName(all,body.optString("name"),"");String id="personal-"+LibraryStore.id();JSONObject topic=Json.obj("id",id,"name",name,"basis","Personal topic");all.put(id,topic);save("khoj.topics",all);return topic;}
        if(p.length==4&&p[1].equals("organization")&&p[2].equals("topics")&&method.equals("PATCH")){JSONObject all=catalogue(),topic=all.optJSONObject(p[3]);if(topic==null)throw new IllegalArgumentException("Topic not found");topic.put("name",uniqueName(all,body.optString("name"),p[3]));if(p[3].startsWith("semantic-"))topic.put("user_named",true);save("khoj.topics",all);return topic;}
        if(route.equals("/organization/topics/assign")||route.equals("/organization/topics/reset")){SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{List<String> documents=ids(body);Set<String> selected=NativeBackend.strings(body.optJSONArray("topic_ids"));if(selected.size()>100)throw new IllegalArgumentException("Choose up to 100 topics");JSONObject all=catalogue();for(String id:selected)if(!all.has(id))throw new IllegalArgumentException("Topic not found");if(selected.isEmpty())selected.add("misc");for(String id:documents)if(route.endsWith("reset"))s.exec("DELETE FROM settings WHERE key=?","khoj.doc.topics:"+id);else save("khoj.doc.topics:"+id,new JSONArray(selected));db.setTransactionSuccessful();return Json.obj("updated",documents.size());}finally{db.endTransaction();}}
        if(p.length>=4&&p[1].equals("organization")&&p[2].equals("documents")){s.document(p[3]);if(p.length==4)return info(p[3]);if(p.length==5&&p[4].equals("name")){if(method.equals("DELETE"))s.exec("DELETE FROM settings WHERE key=?","khoj.name:"+p[3]);else save("khoj.name:"+p[3],NativeBackend.name(body.optString("name")));return info(p[3]);}}
        if(route.equals("/organization/move"))return move(body);
        if(p.length==5&&p[1].equals("organization")&&p[2].equals("moves")&&p[4].equals("undo"))return undo(p[3]);
        if(p.length==4&&p[1].equals("documents")&&p[3].equals("recovery"))return recovery(p[2]);
        return null;
    }
    String uniqueName(JSONObject all,String proposed,String except){String name=NativeBackend.name(proposed);for(JSONObject topic:LibraryStore.objects(topics()))if(!topic.optString("id").equals(except)&&topic.optString("name").equalsIgnoreCase(name))throw new IllegalArgumentException("A topic already has that name");return name;}
    void collision(String id,String folder){JSONObject doc=s.document(id);if(s.query("SELECT id FROM documents WHERE folder_id=? AND sha256=? AND id!=? AND trashed=0",folder,doc.optString("sha256"),id).length()>0)throw new IllegalArgumentException("That folder already contains this PDF");}
    JSONObject move(JSONObject body)throws Exception {SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{List<String> documents=ids(body);String target=body.getString("folder_id");s.one("SELECT id FROM folders WHERE id=?",target);JSONArray before=new JSONArray();Set<String> hashes=new HashSet<>();for(String id:documents){JSONObject doc=s.document(id);if(!hashes.add(doc.optString("sha256")))throw new IllegalArgumentException("Select only one copy of each PDF");collision(id,target);if(!doc.optString("folder_id").equals(target))before.put(Json.obj("id",id,"folder_id",doc.optString("folder_id"),"version",doc.optInt("version")+1));}for(JSONObject old:LibraryStore.objects(before))s.exec("UPDATE documents SET folder_id=?,version=version+1,updated_at=? WHERE id=?",target,LibraryStore.now(),old.optString("id"));String token=before.length()==0?null:LibraryStore.id();if(token!=null)save("khoj.move:"+token,before);db.setTransactionSuccessful();return Json.obj("updated",before.length(),"undo_token",token);}finally{db.endTransaction();}}
    JSONObject undo(String token){SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{String saved=setting("khoj.move:"+token);if(saved==null)throw new IllegalArgumentException("This move can no longer be undone");JSONArray previous=array(saved);for(JSONObject old:LibraryStore.objects(previous)){JSONObject doc=s.document(old.optString("id"));if(doc.optInt("version")!=old.optInt("version")||doc.optInt("trashed")!=0)throw new IllegalArgumentException("A file changed after the move; move it back manually");s.one("SELECT id FROM folders WHERE id=?",old.optString("folder_id"));collision(doc.optString("id"),old.optString("folder_id"));}for(JSONObject old:LibraryStore.objects(previous))s.exec("UPDATE documents SET folder_id=?,version=version+1,updated_at=? WHERE id=?",old.optString("folder_id"),LibraryStore.now(),old.optString("id"));s.exec("DELETE FROM settings WHERE key=?","khoj.move:"+token);db.setTransactionSuccessful();return Json.obj("updated",previous.length());}finally{db.endTransaction();}}
    void restoreSettings(SQLiteDatabase restored,Map<String,String> documents)throws Exception {
        JSONObject merged=catalogue();
        try(android.database.Cursor cursor=restored.rawQuery("SELECT key,value FROM settings WHERE key LIKE 'khoj.%'",null)){
            while(cursor.moveToNext()){String key=cursor.getString(0),value=cursor.getString(1);
                if(key.equals("khoj.topics")){JSONObject previous=Json.parse(value);Iterator<String> keys=previous.keys();while(keys.hasNext()){String id=keys.next();if(!merged.has(id))merged.put(id,previous.getJSONObject(id));}}
                for(String prefix:new String[]{"khoj.name:","khoj.doc.topics:","khoj.modified:"})if(key.startsWith(prefix)){String id=documents.get(key.substring(prefix.length()));if(id!=null)save(prefix+id,value);}
            }
        }
        save("khoj.topics",merged);
        b.libraryQoL.restoreSettings(restored,documents);
    }
    JSONObject recovery(String id)throws Exception {JSONObject doc=s.document(id);JSONObject source=Json.obj("code","available","message","The PDF saved in Khoj is available.","actions",Json.arr("retry"));try{s.source(id,false);}catch(IOException error){source=Json.obj("code","missing","message","The original PDF is unavailable or file access was turned off. Allow access and scan again, restore a backup, or replace the file. Indexed text is retained.","actions",Json.arr("replace"));}Object extraction=doc.optString("status").equals("indexed")?null:Json.obj("code",doc.optString("status"),"message","Some pages have no readable text. Try reading scanned pages, retry, or replace the PDF.","page_statuses",new JSONObject());return Json.obj("document_id",id,"source",source,"extraction",extraction,"original_path","Saved in Khoj on this phone","can_reconnect",false);}
    JSONObject about(){return Json.obj("name","Khoj","version","0.5.0","display_version","v0.5","updates",Json.obj("mode","manual","automatic_checks",false,"instructions","Install the newer Khoj APK from the same publisher over this app to retain your files. Do not uninstall first. Use a backup before updating. Updates are not downloaded automatically."),"privacy",Json.arr("Phone-wide PDF discovery, search, file reading and AI run on this phone. This APK has no Internet permission and does not send documents or searches to a server.","Whole-phone PDF discovery requests Android file access only when you choose it. Scanned originals stay in place; other apps' private storage cannot be read. Files added manually are retained inside Khoj.","The local database is not encrypted. Password-protected backups are available. Microphone access is requested only for optional on-device voice search.","Support reports are saved only when you ask. You choose whether to share them."),"diagnostics",Json.obj("includes","Khoj and Android versions, memory, CPU processing, and file/job counts.","excludes","Document contents, pages, filenames, paths, searches, feedback, keys, raw errors and logs."));}
    JSONObject embeddingPerformance(){long[] p=NativeModels.performance();return Json.obj("scope","this_process","completed_passages",p[0],"total_ms",p[1]/1000.0,"contexts_created",p[2],"model_loads",p[3],"inference_batches",p.length>4?p[4]:p[0],"input_tokens",p.length>5?p[5]:0);}
    JSONObject diagnostics(){ActivityManager.MemoryInfo memory=new ActivityManager.MemoryInfo();((ActivityManager)b.context.getSystemService(android.content.Context.ACTIVITY_SERVICE)).getMemoryInfo(memory);JSONObject statuses=new JSONObject();for(String state:new String[]{"queued","running","skipping","skipped","completed","failed","interrupted","recovered"})try{statuses.put(state,s.one("SELECT count(*) n FROM tasks WHERE status=?",state).optInt("n"));}catch(JSONException ignored){}return Json.obj("schema","khoj-diagnostics-v1","product",Json.obj("name","Khoj","version","0.5.0","display_version","v0.5"),"system",Json.obj("os","Android","sdk",Build.VERSION.SDK_INT,"ram_bytes",memory.totalMem,"available_ram_bytes",memory.availMem),"runtime",Json.obj("device","cpu","cloud_enabled",false,"cpu_features",NativeModels.cpuInfo(),"embedding_performance",embeddingPerformance()),"library",Json.obj("documents",s.one("SELECT count(*) n FROM documents WHERE trashed=0").optInt("n"),"pages",s.one("SELECT count(*) n FROM pages").optInt("n"),"database_bytes",b.context.getDatabasePath("library.sqlite3").length()),"tasks",statuses);}
    synchronized String retry(String id){JSONObject task=s.one("SELECT * FROM tasks WHERE id=?",id);if(Arrays.asList("queued","running","skipping").contains(task.optString("status")))return id;if(!Arrays.asList("failed","interrupted","skipped").contains(task.optString("status")))throw new IllegalArgumentException("Only a failed, interrupted or skipped file can be retried");String uri=task.optString("source_uri"),cached=task.optString("source_path");if(!cached.isEmpty()&&new File(cached).isFile())uri=Uri.fromFile(new File(cached)).toString();s.exec("UPDATE tasks SET source_uri=?,status='queued',progress=NULL,error=NULL,result=NULL WHERE id=?",uri,id);if(task.optInt("is_reference")!=0){File source=new File(Uri.parse(uri).getPath());s.exec("UPDATE phone_scan_files SET task_id=?,state='queued',signature=?,error=NULL WHERE path=?",id,source.length()+":"+source.lastModified(),source.getAbsolutePath());}b.indexing.submit(()->b.importTask(id));return id;}
    void resume(){for(JSONObject task:LibraryStore.objects(s.query("SELECT id FROM tasks WHERE status='interrupted'")))try{retry(task.optString("id"));}catch(Exception ignored){}}
    WebResourceResponse preview(String id,Uri uri)throws Exception {
        JSONObject doc=s.document(id);String revision=uri.getQueryParameter("revision");if(revision!=null&&!revision.isEmpty()&&!revision.equals(doc.optString("sha256")))throw new IOException("This file changed. Search again.");
        int number=Integer.parseInt(NativeBackend.param(uri,"page","1"));String chunkId=uri.getQueryParameter("chunk_id");JSONObject chunk=s.one("SELECT text FROM chunks WHERE id=? AND document_id=? AND page_number=?",chunkId,id,String.valueOf(number));
        File file=s.source(id,false);if(doc.optString("format").equals("pdf")&&!LibraryStore.hash(file).equals(doc.optString("sha256")))throw new IOException("The saved PDF changed. Replace it before opening.");
        byte[] image;int width,height,count;
        try(ParcelFileDescriptor descriptor=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(descriptor);PdfRenderer.Page page=renderer.openPage(number-1)){
            width=900;height=Math.max(1,Math.round(width*(float)page.getHeight()/page.getWidth()));if(height>2400){width=Math.max(1,width*2400/height);height=2400;}
            Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);try{bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint();paint.setColor(Color.argb(105,255,213,44));JSONArray boxes=b.highlight(id,number,chunk.optString("text")).optJSONArray("boxes");count=boxes.length();for(int i=0;i<count;i++){JSONArray box=boxes.optJSONArray(i);canvas.drawRect((float)box.optDouble(0)*width,(float)box.optDouble(1)*height,(float)(box.optDouble(0)+box.optDouble(2))*width,(float)(box.optDouble(1)+box.optDouble(3))*height,paint);}ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);image=out.toByteArray();}finally{bitmap.recycle();}
        }
        return new WebResourceResponse("image/png",null,200,"OK",Map.of("Cache-Control","no-store","X-Highlight-Count",String.valueOf(count),"X-Page-Width",String.valueOf(width),"X-Page-Height",String.valueOf(height)),new ByteArrayInputStream(image));
    }
}
